{
  "section": "research",
  "available_sections": [
    {
      "id": "core",
      "description": "Required Python/signal rules and revision lifecycle."
    },
    {
      "id": "research",
      "description": "Required research choices, defaults and explicit inheritance."
    },
    {
      "id": "evidence",
      "description": "Parameter proposals, source claims and saved trading formulas."
    },
    {
      "id": "indicators",
      "description": "Installed indicator catalog and selected API/source reference."
    },
    {
      "id": "example",
      "description": "Complete Python and YAML example to adapt."
    },
    {
      "id": "configuration",
      "description": "Full execution YAML schema and metric settings."
    },
    {
      "id": "runtime",
      "description": "Generated isolation, resource policy and failure recovery."
    }
  ],
  "content": {
    "research_schema": {
      "$defs": {
        "InheritResearchSpec": {
          "additionalProperties": false,
          "description": "Explicitly inherit omitted research choices from one selected fixed revision.",
          "properties": {
            "kind": {
              "const": "inherit_selected_revision",
              "title": "Kind",
              "type": "string"
            },
            "strategy_outline": {
              "minLength": 1,
              "title": "Strategy Outline",
              "type": "string"
            },
            "symbol": {
              "minLength": 1,
              "title": "Symbol",
              "type": "string"
            },
            "start_date": {
              "format": "date-time",
              "title": "Start Date",
              "type": "string"
            },
            "end_date": {
              "format": "date-time",
              "title": "End Date",
              "type": "string"
            },
            "timeframe": {
              "minLength": 1,
              "title": "Timeframe",
              "type": "string"
            },
            "init_cash": {
              "exclusiveMinimum": 0,
              "title": "Init Cash",
              "type": "number"
            },
            "fees": {
              "minimum": 0,
              "title": "Fees",
              "type": "number"
            },
            "slippage": {
              "minimum": 0,
              "title": "Slippage",
              "type": "number"
            },
            "annualization": {
              "anyOf": [
                {
                  "enum": [
                    "market",
                    "unavailable"
                  ],
                  "type": "string"
                },
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                }
              ],
              "title": "Annualization"
            }
          },
          "required": [
            "kind"
          ],
          "title": "InheritResearchSpec",
          "type": "object"
        },
        "NewResearchSpec": {
          "additionalProperties": false,
          "description": "New research needs all four user choices; only simulation costs have defaults.",
          "properties": {
            "kind": {
              "const": "new",
              "title": "Kind",
              "type": "string"
            },
            "strategy_outline": {
              "minLength": 1,
              "title": "Strategy Outline",
              "type": "string"
            },
            "symbol": {
              "minLength": 1,
              "title": "Symbol",
              "type": "string"
            },
            "start_date": {
              "format": "date-time",
              "title": "Start Date",
              "type": "string"
            },
            "end_date": {
              "format": "date-time",
              "title": "End Date",
              "type": "string"
            },
            "timeframe": {
              "minLength": 1,
              "title": "Timeframe",
              "type": "string"
            },
            "init_cash": {
              "exclusiveMinimum": 0,
              "title": "Init Cash",
              "type": "number"
            },
            "fees": {
              "minimum": 0,
              "title": "Fees",
              "type": "number"
            },
            "slippage": {
              "minimum": 0,
              "title": "Slippage",
              "type": "number"
            },
            "annualization": {
              "anyOf": [
                {
                  "enum": [
                    "market",
                    "unavailable"
                  ],
                  "type": "string"
                },
                {
                  "exclusiveMinimum": 0,
                  "type": "number"
                }
              ],
              "default": "market",
              "title": "Annualization"
            }
          },
          "required": [
            "strategy_outline",
            "symbol",
            "start_date",
            "end_date",
            "timeframe",
            "kind"
          ],
          "title": "NewResearchSpec",
          "type": "object"
        }
      },
      "discriminator": {
        "mapping": {
          "inherit_selected_revision": "#/$defs/InheritResearchSpec",
          "new": "#/$defs/NewResearchSpec"
        },
        "propertyName": "kind"
      },
      "oneOf": [
        {
          "$ref": "#/$defs/NewResearchSpec"
        },
        {
          "$ref": "#/$defs/InheritResearchSpec"
        }
      ]
    },
    "policy": {
      "policy_version": "research-v1",
      "required_inputs": [
        "strategy_outline",
        "symbol",
        "start_date",
        "end_date",
        "timeframe"
      ],
      "simulation_defaults": {
        "init_cash": 10000.0,
        "init_cash_unit": "quote_currency",
        "fees": 0.0006,
        "slippage": 0.0005,
        "description": "Simulation assumptions, not current exchange fees. Explicit valid values take priority; zero costs remain zero. Initial capital applies to signal mode and does not alter volume strategy semantics."
      },
      "annualization": {
        "basis": "observed UTC daily equity returns",
        "crypto_daily_periods_per_year": 365.0,
        "market_policy": "365 is inferred only for a provider whose registered asset classes are exclusively crypto. Mixed providers, including Yahoo, require an explicit positive factor or 'unavailable'.",
        "sampling": "Daily statistics require a declared bar frequency no coarser than one day. A factor does not make weekly/monthly bars into daily observations."
      },
      "provenance": "request/project_default/selected_revision describe configuration origins, not proof of human input. Inheritance requires a selected immutable revision.",
      "data_selection": "Specify data.source or data.requirements.market.source. Providers with market type choices also require an explicit data.market_type."
    },
    "notes": [
      "Before authoring or preparing, obtain the user's strategy idea, instrument, date interval and candle timeframe. A vague trading idea is sufficient; missing choices require clarification, not values copied from examples or a bundled configuration.",
      "research owns market/date/capital/cost/annualization choices. The YAML supplies strategy class/parameters, explicit data source, features, execution controls and validation. When saving, duplicate research fields in YAML must agree; the backend materializes the complete immutable base configuration before program checks.",
      "Omit unspecified capital and costs to use the maintained simulation policy. Preserve the user's explicit valid values, including zero. Do not supply guessed values and describe them as user instructions.",
      "inherit_selected_revision is an explicit choice to reuse one identified generated revision; it is not a missing-value fallback. Supply that exact revision_id when preparing, or expected_revision_id when repairing. Bundled sample dates cannot supply missing choices.",
      "Research periods select candle timestamps with start_date <= timestamp <= end_date, including both endpoints when matching candles exist. Dates without timezone are interpreted as UTC; explicit offsets convert to UTC. Date-only values mean 00:00:00 UTC, not the whole final day. Review these exact resolved bounds with the user. No history is read before approval, so actual available bars and gaps are still unverified.",
      "Use annualization='market' only when a supported market policy applies. Otherwise propose and disclose a justified positive daily factor, or obtain an explicit choice to proceed with annualization unavailable. Do not apply a universal stock-market day count.",
      "Source labels describe what the backend resolved from this request, the project policy or a selected revision. They do not establish that a human supplied or approved those choices."
    ]
  }
}

{
  "section": "evidence",
  "available_sections": [
    {
      "id": "core",
      "description": "Required Python/signal rules and revision lifecycle."
    },
    {
      "id": "research",
      "description": "Required research choices, defaults and explicit inheritance."
    },
    {
      "id": "evidence",
      "description": "Parameter proposals, source claims and saved trading formulas."
    },
    {
      "id": "indicators",
      "description": "Installed indicator catalog and selected API/source reference."
    },
    {
      "id": "example",
      "description": "Complete Python and YAML example to adapt."
    },
    {
      "id": "configuration",
      "description": "Full execution YAML schema and metric settings."
    },
    {
      "id": "runtime",
      "description": "Generated isolation, resource policy and failure recovery."
    }
  ],
  "content": {
    "selection": [
      "Preserve explicit user choices. When parameters are omitted, propose a small fixed set of justified alternatives for confirmation. Multiple sets are normal comparison, not permission to optimize against returns.",
      "Use the host's actual web capability to check primary references for conventional parameters. Do not infer capability from its brand. The server does not search the web. Record only sources actually retrieved or supplied by the user, including their title, URL, timezone-aware accessed_at, retrieval_kind and the limited claim each supports.",
      "Without retrieval, do not claim common, verified or optimal settings. Offer clearly labelled model_proposal alternatives and explain the uncertainty; if there is no defensible range, ask the user for a range or whether to use the proposed range. Do not invent references."
    ],
    "recording": [
      "After checking the selected implementation, save_research_evidence records a draft. Use its evidence_id in prepare_backtest, prepare_comparison, prepare_walk_forward or prepare_optimization. Every correction creates a new record; a prepared plan retains its own fixed copy. The tool schema is the authoritative field definition.",
      "Write plain-language entry, holding and exit conditions, direction, warm-up behavior and limitations; include corresponding formulas and variable units for advanced readers. For ML, state features, fitted prediction and decision rules honestly, without inventing a simple indicator formula or implying an illustrative case is representative. Explain the actual code; the server cannot prove formula/code equivalence.",
      "Check formulas against the implementation before saving. For stateful strategies state initial state, rule precedence and mutually exclusive updates; use guarded conditions or one complete piecewise transition. Separate rules must not assign contradictory else branches to the same signal. State window inclusivity, minimum observations and variance conventions such as ddof when used. Warm-up conditions must describe missing data, not the opposite. Distinguish initial warm-up from later missing inputs: describe both the retained internal state and emitted signal as the code actually handles them. Include indicator definitions needed to interpret a rule, not only a library function name. Distinguish raw execution-price inputs from actual fills after costs. These checks remain the host's responsibility, not proof supplied by synthetic validation.",
      "Provide presentation descriptions for every effective constructor leaf. Parameter paths are JSON pointers (escape ~ as ~0 and / as ~1). The backend resolves values, including defaults and nested arrays; parameter_provenance labels their origin without resupplying values.",
      "Each declaration covers target_ids × parameter_paths exactly once. Use base for one execution; candidate_1, candidate_2, etc. in fixed comparison order. Optimization needs base plus search_<group>_<option> for each merged search-axis subtree, with one-based indexes in sorted parameter-key order. These identify axis options, not Cartesian trials. Missing, duplicate, unknown or overlapping bindings are rejected.",
      "Origins are user (explicit user values), project_default (actual selected project configuration), reference (cited value claims), or model_proposal (unverified proposal). Only reference requires source_claims. Each cited claim must match the bound value including JSON type. Group differently valued referenced settings separately. A formula reference alone does not justify a parameter's value.",
      "If preparation returns research_evidence_binding_invalid, inspect required_parameter_bindings and required_parameter_paths; explain every returned value, save corrected evidence and prepare again. Do not change research or strip training requirements to bypass errors."
    ],
    "confirmation_and_results": [
      "Preparation checks only code/settings/synthetic fixtures. It adds the backend's versioned execution assumptions to the saved confirmation. Present the returned plain-language summary and HTML link, then wait for explicit approval. Do not download history, train or backtest first.",
      "The resulting HTML preserves formulas, origins, sources, limitations and saved execution assumptions. Report sections are discoverable through get_report_sections; research is included in standard recipes. Generate a whole comparison by comparison_job_id even if every candidate fails. A recorded reference is a client assertion, not proof of browsing, semantic accuracy, profitability or strategy suitability."
    ],
    "unsourced_single_execution_example": {
      "schema_version": 1,
      "presentation": {
        "title": "Long-only moving-average research",
        "summary": "Hold above the moving average; otherwise exit.",
        "parameter_descriptions": {
          "/period": {
            "label": "Moving-average lookback",
            "description": "Completed closes used in the average.",
            "unit": "candles"
          }
        }
      },
      "rules": [
        {
          "rule_id": "position",
          "condition": "A complete, finite lookback is available.",
          "action": "Hold long above the average; otherwise stay flat.",
          "formula": "signal[t] = 1 if close[t] > SMA(close, period)[t] else 0",
          "variables": [
            {
              "symbol": "t",
              "meaning": "Completed candle",
              "unit": "candle"
            },
            {
              "symbol": "period",
              "meaning": "Lookback",
              "unit": "candles"
            }
          ],
          "source_ids": []
        }
      ],
      "limits": [
        "Illustrative model proposal; no external reference or return claim."
      ],
      "sources": [],
      "parameter_provenance": [
        {
          "target_ids": [
            "base"
          ],
          "parameter_paths": [
            "/period"
          ],
          "provenance": "model_proposal",
          "reason": "An explicitly unverified proposal for user review.",
          "source_claims": []
        }
      ]
    }
  }
}

